package com.stockpulse.ai;

import com.stockpulse.advisor.*;
import org.springframework.stereotype.Component;

@Component
public class AiAdvisor implements CommerceAdvisor {
    private final LlmClient client; private final RecommendationParser parser; private final RuleBasedAdvisor fallback; private final PromptTemplateService prompts;
    public AiAdvisor(LlmClient client, RecommendationParser parser, RuleBasedAdvisor fallback, PromptTemplateService prompts) { this.client = client; this.parser = parser; this.fallback = fallback; this.prompts = prompts; }
    @Override public String name() { return "ai"; }
    @Override public PricingRecommendation recommendPricing(AdvisorContext context) { try { PricingRecommendation result = parser.pricing(client.complete(prompt("pricing", context))); validatePricing(result, context); return new PricingRecommendation(result.recommendedPrice(), result.direction(), result.confidence(), result.reasoning(), com.stockpulse.suggestion.SuggestionSource.AI, null); } catch (RuntimeException e) { PricingRecommendation r = fallback.recommendPricing(context); return new PricingRecommendation(r.recommendedPrice(), r.direction(), r.confidence(), "AI fallback: " + safe(e), com.stockpulse.suggestion.SuggestionSource.AI_FALLBACK_RULE_BASED, safe(e)); } }
    @Override public ReorderRecommendation recommendReorder(AdvisorContext context) { try { ReorderRecommendation result = parser.reorder(client.complete(prompt("reorder", context))); if (result.recommendedQuantity() > context.reorderThreshold() * 20) throw new IllegalArgumentException("reorder quantity exceeds cap"); return new ReorderRecommendation(result.recommendedQuantity(), result.suggestedLeadTimeDays(), result.confidence(), result.reasoning(), com.stockpulse.suggestion.SuggestionSource.AI, null); } catch (RuntimeException e) { ReorderRecommendation r = fallback.recommendReorder(context); return new ReorderRecommendation(r.recommendedQuantity(), r.suggestedLeadTimeDays(), r.confidence(), "AI fallback: " + safe(e), com.stockpulse.suggestion.SuggestionSource.AI_FALLBACK_RULE_BASED, safe(e)); } }
    private String prompt(String type, AdvisorContext c) { return prompts.render(type, c.triggerReason(), "Product " + c.productName() + ", stock " + c.stockLevel() + " vs threshold " + c.reorderThreshold() + ", velocity " + c.demandVelocity() + " vs category average " + c.categoryAverageVelocity() + ". Current price: " + c.currentPrice()); }
    private void validatePricing(PricingRecommendation r, AdvisorContext c) { java.math.BigDecimal min = c.currentPrice().multiply(new java.math.BigDecimal("0.5")); java.math.BigDecimal max = c.currentPrice().multiply(new java.math.BigDecimal("2")); if (r.recommendedPrice().compareTo(min) < 0 || r.recommendedPrice().compareTo(max) > 0) throw new IllegalArgumentException("price outside allowed range"); if (r.direction() == com.stockpulse.suggestion.PricingDirection.INCREASE && r.recommendedPrice().compareTo(c.currentPrice()) <= 0) throw new IllegalArgumentException("increase direction is inconsistent"); if (r.direction() == com.stockpulse.suggestion.PricingDirection.DECREASE && r.recommendedPrice().compareTo(c.currentPrice()) >= 0) throw new IllegalArgumentException("decrease direction is inconsistent"); if (r.direction() == com.stockpulse.suggestion.PricingDirection.HOLD && r.recommendedPrice().compareTo(c.currentPrice()) != 0) throw new IllegalArgumentException("hold direction is inconsistent"); }
    private String safe(RuntimeException e) { return e.getMessage() == null ? "recommendation validation or gateway failure" : e.getMessage(); }
}